mapper.select:
WITH ROUTE_USER_RANK_LIST AS ( SELECT A.STTN_INFO , A.USER_CNT FROM ( SELECT gbr.ST_STA_NM || '-' || gbr.ED_STA_NM as STTN_INFO , SUM(mbrpa.PASS_1 + mbrpa.PASS_2 + mbrpa.PASS_3) as USER_CNT FROM MRT_BUS_ROUTE_PASNG_ANAL mbrpa INNER JOIN GGBIS_BUS_ROUTE gbr ON mbrpa.BUS_ROUTE_ID = gbr.ROUTE_ID WHERE 1=1
AND TO_CHAR(mbrpa.ANLS_DT, 'YYYY-MM-DD') = #{searchTime}
GROUP BY gbr.ST_STA_NM, gbr.ED_STA_NM ORDER BY USER_CNT DESC LIMIT 5 )A GROUP BY A.STTN_INFO, A.USER_CNT ) SELECT ARRAY_TO_STRING(ARRAY_AGG(STTN_INFO), ',') AS "sttnInfoArr" , ARRAY_TO_STRING(ARRAY_AGG(USER_CNT), ',') AS "userCntArr" FROM ROUTE_USER_RANK_LIST
